"""Pages tab — discovers and renders HTML files from the working directory.

Scans WORK_DIR for *.html files, presents a dropdown selector, and displays
the selected file in an HtmlFrame.  File-watch polling detects new/removed
files and content changes, firing a bell notification on updates.
"""

from __future__ import annotations

import logging
import time
import tkinter as tk
from tkinter import ttk
from pathlib import Path
from typing import Any

from personal_assistant.models import NotifyTabCallback
from personal_assistant.config import (
    BG_OUTPUT,
    BG_WINDOW,
    COLOR_BUTTON,
    COLOR_BUTTON_ACTIVE,
    COLOR_HTML_FALLBACK_BG,
    COLOR_HTML_FALLBACK_FG,
    FG_DIM,
    FG_TEXT,
    FILE_WATCH_INTERVAL_MS,
    FONT_NAME_BODY,
    PAD,
    WORK_DIR,
)

logger = logging.getLogger(__name__)

# CSS injected into HTML frames for spacing
SPACING_CSS = (
    "body { line-height: 1.5; }"
    " h1, h2, h3, h4, h5 { margin-top: 1.2em; margin-bottom: 0.4em; }"
    " p { margin-top: 0.4em; margin-bottom: 0.4em; }"
    " ul, ol { margin-top: 0.4em; margin-bottom: 0.4em; }"
    " li { margin-bottom: 0.2em; }"
    " table { margin-bottom: 1em; }"
    " td, th { padding: 4px 8px; }"
)


def _format_age(seconds: int) -> str:
    """Format an age in seconds to a human-readable string."""
    if seconds < 60:
        return f"{seconds}s ago"
    elif seconds < 3600:
        return f"{seconds // 60}m ago"
    elif seconds < 86400:
        hours = seconds // 3600
        minutes = (seconds % 3600) // 60
        return f"{hours}h {minutes}m ago"
    else:
        return f"{seconds // 86400}d ago"


def scan_html_files() -> list[Path]:
    """Return sorted list of *.html files in WORK_DIR."""
    return sorted(WORK_DIR.glob("*.html"))


class PagesTab:
    """Pages tab — discovers and renders HTML files from the working directory."""

    def __init__(
        self,
        parent: tk.Frame,
        root: tk.Tk,
        *,
        notify_tab: NotifyTabCallback | None = None,
    ) -> None:
        self._parent = parent
        self._root = root
        self._notify_tab = notify_tab
        self._watch_timer: str | None = None
        self._html_frame: Any = None
        self._mtimes: dict[str, float] = {}
        self._build()
        self._start_watch()

    def _build(self) -> None:
        # Control bar
        controls = tk.Frame(self._parent, bg=BG_WINDOW)
        controls.pack(fill=tk.X, padx=PAD, pady=(PAD, 0))

        self._file_var = tk.StringVar(value="")
        self._combo = ttk.Combobox(
            controls,
            textvariable=self._file_var,
            state="readonly",
            font=FONT_NAME_BODY,
        )
        self._combo.pack(side=tk.LEFT, fill=tk.X, expand=True)
        self._combo.bind("<<ComboboxSelected>>", self._on_select)

        tk.Button(
            controls,
            text="\U0001f504",
            command=self._reload_current,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_NAME_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=4,
        ).pack(side=tk.RIGHT, padx=(4, 0))

        self._status_var = tk.StringVar(value="")
        tk.Label(
            controls,
            textvariable=self._status_var,
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=FONT_NAME_BODY,
        ).pack(side=tk.RIGHT, padx=(PAD, 0))

        # HTML display
        self._build_html_frame()

        # Initial scan
        self._refresh_file_list()

    def _build_html_frame(self) -> None:
        """Build the HTML display frame."""
        try:
            from tkinterweb import HtmlFrame

            import webbrowser

            self._html_frame = HtmlFrame(
                self._parent,
                messages_enabled=False,
                dark_theme_enabled=True,
                on_link_click=lambda url: webbrowser.open(url),
            )
            self._html_frame.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
        except ImportError:
            fallback = tk.Text(
                self._parent,
                bg=BG_OUTPUT,
                fg=FG_TEXT,
                font=FONT_NAME_BODY,
                wrap=tk.WORD,
                state=tk.DISABLED,
                highlightthickness=0,
            )
            fallback.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            fallback.configure(state=tk.NORMAL)
            fallback.insert(
                "1.0",
                "tkinterweb not installed. " "Run: pip install tkinterweb[recommended]",
            )
            fallback.configure(state=tk.DISABLED)

    def _refresh_file_list(self) -> None:
        """Re-scan WORK_DIR for HTML files and update the dropdown."""
        files = scan_html_files()
        names = [f.name for f in files]
        current = self._file_var.get()

        self._combo["values"] = names

        if not names:
            self._file_var.set("")
            self._show_placeholder()
            return

        if current in names:
            # Keep current selection
            pass
        else:
            # Select first file
            self._file_var.set(names[0])
            self._load_file(names[0])

    def _on_select(self, _event: Any) -> None:
        """Handle dropdown selection change."""
        name = self._file_var.get()
        if name:
            self._load_file(name)

    def _load_file(self, name: str) -> None:
        """Load an HTML file into the display."""
        if self._html_frame is None:
            return
        path = WORK_DIR / name
        if path.exists():
            content = path.read_text(encoding="utf-8")
            self._html_frame.load_html(content)
            self._html_frame.add_css(SPACING_CSS)
            if hasattr(self, "_font_scale_css"):
                self._html_frame.add_css(self._font_scale_css)
            mtime = path.stat().st_mtime
            age_seconds = int(time.time() - mtime)
            self._status_var.set(f"Updated {_format_age(age_seconds)}")
        else:
            self._show_placeholder()

    def _show_placeholder(self) -> None:
        """Show a placeholder when no HTML files are available."""
        if self._html_frame is None:
            return
        self._html_frame.load_html(
            f"<html><body style='background:{COLOR_HTML_FALLBACK_BG};"
            f"color:{COLOR_HTML_FALLBACK_FG};"
            "font-family:sans-serif;padding:20px'>"
            "<p>No HTML files found in working directory.</p>"
            f"<code>{WORK_DIR}</code></body></html>"
        )
        self._status_var.set("No pages")

    def _reload_current(self) -> None:
        """Reload the currently selected file."""
        name = self._file_var.get()
        if name:
            self._load_file(name)

    # --- File watching ---

    def _start_watch(self) -> None:
        """Start the file-watch timer."""
        self._poll_files()

    def _poll_files(self) -> None:
        """Check for new/removed/changed HTML files."""
        files = scan_html_files()
        current_names = {f.name for f in files}
        previous_names = set(self._mtimes.keys())

        # Detect additions or removals
        if current_names != previous_names:
            self._refresh_file_list()

        # Check mtimes for changes
        changed = False
        new_mtimes: dict[str, float] = {}
        for f in files:
            mtime = f.stat().st_mtime
            new_mtimes[f.name] = mtime
            old_mtime = self._mtimes.get(f.name, 0.0)
            if old_mtime != 0.0 and mtime != old_mtime:
                changed = True

        self._mtimes = new_mtimes

        if changed:
            # Reload if current file changed
            current = self._file_var.get()
            if current and current in new_mtimes:
                self._load_file(current)
            if self._notify_tab is not None:
                self._notify_tab("Pages")

        # Update age display for current file
        current = self._file_var.get()
        if current and current in new_mtimes:
            age_seconds = int(time.time() - new_mtimes[current])
            self._status_var.set(f"Updated {_format_age(age_seconds)}")

        self._watch_timer = self._root.after(FILE_WATCH_INTERVAL_MS, self._poll_files)

    # --- Public API ---

    def set_font_scale(self, scale: float) -> None:
        """Apply font scaling to the HTML frame via CSS."""
        self._font_scale_css = f"body {{ font-size: {scale * 100:.0f}%; }}"
        if self._html_frame is not None:
            self._html_frame.add_css(self._font_scale_css)

    def on_destroy(self) -> None:
        """Called during dashboard shutdown to clean up resources."""
        if self._watch_timer is not None:
            self._root.after_cancel(self._watch_timer)
            self._watch_timer = None
